using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class TimeoutRecoveryRescore{
 public static int Main(string[] args){try{var root=Path.GetFullPath(args[0]);var j=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};string dir=Path.Combine(root,"extension/data/replier-grounded-checks");var input=SceneMaterial.Json(File.ReadAllText(Path.Combine(dir,"residency-benchmark-final-buffer-check-latest.json")));var run=((object[])CaptionService.Get(input,"runs"))[0];var video=j.Deserialize<Video>(j.Serialize(CaptionService.Get(run,"video")));var result=j.Deserialize<DualCommentResult>(j.Serialize(CaptionService.Get(run,"result")));var rows=result.Batches.SelectMany(b=>b.Result.Comments).ToList();var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load(video.Id);var prep=Stopwatch.StartNew();
 using(var gemma=new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),DualCommentService.Models[0],true))using(var qwen=new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),DualCommentService.Models[1],true))using(var limit=new CancellationTokenSource(TimeSpan.FromSeconds(150))){gemma.Warm(limit.Token).GetAwaiter().GetResult();qwen.Warm(limit.Token).GetAwaiter().GetResult();prep.Stop();var watch=Stopwatch.StartNew();var scorer=new CombinedFitScoring(new FitScoring(gemma),new FitScoring(qwen),gemma.Unload,false);scorer.Evaluate(video,content,rows,limit.Token).GetAwaiter().GetResult();new SceneTieBreaker((name,b,t)=>(name==qwen.Name?qwen:gemma).Chat(b,t),name=>System.Threading.Tasks.Task.FromResult(0),true).Apply(video,rows,limit.Token).GetAwaiter().GetResult();watch.Stop();var best=rows.Where(c=>c.FitEligible==true).OrderByDescending(c=>c.TiePreference).ThenByDescending(c=>c.FitScore).FirstOrDefault();File.WriteAllText(Path.Combine(dir,"timeout-recovery-rescore.json"),j.Serialize(new{prepare_seconds=prep.Elapsed.TotalSeconds,seconds=watch.Elapsed.TotalSeconds,video=video,rows=rows,best=best,fresh_generation=false}));Console.WriteLine("RESCORE seconds="+watch.Elapsed.TotalSeconds.ToString("F3")+" prep="+prep.Elapsed.TotalSeconds.ToString("F3")+" eligible="+rows.Count(c=>c.FitEligible==true));Console.WriteLine("BEST "+(best==null?"NONE":best.Text));if(best!=null)Console.WriteLine("QUOTE "+best.GroundingQuote+" SCORE "+best.FitScore);return best==null?2:0;}
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
